/* From Uiverse.io by barisdogansutcu  - Tags: button, button anatomy, customize */
.__UIV_SCOPE__ .button {
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-size: 14px;
  background-image: linear-gradient(#3470fa, #313ed7);
  color: white;
  border: solid 2px #0618db;
  height: 50px;
  padding: 0px 20px;
  border-radius: 5px;
  font-weight: 600;
  transform: scale(0.89);
  position: relative;
}
.__UIV_SCOPE__ .button:not(:hover) .hide,
.__UIV_SCOPE__ .button:not(:hover) .icon::before,
.__UIV_SCOPE__ .button:not(:hover) .icon::after {
  opacity: 0;
  visibility: hidden;
  transform: scale(1.4);
}
.__UIV_SCOPE__ .hide {
  transition: all 0.2s ease;
}
.__UIV_SCOPE__ .button:active {
  background-image: linear-gradient(#313ed7, #3470fa);
  border-color: #313ed7;
}
.__UIV_SCOPE__ .icon {
  position: relative;
}
.__UIV_SCOPE__ .icon::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 6px;
  height: 6px;
  transform: translate(-50%, -50%);
  background-color: rgb(255, 0, 170);
  border-radius: 100%;
}
.__UIV_SCOPE__ .icon::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  transform: translate(-19%, -60%);
  width: 100px;
  height: 33px;
  background-color: transparent;
  border-radius: 12px 22px 2px 2px;
  border-right: solid 2px rgb(255, 0, 170);
  border-top: solid 2px transparent;
}
.__UIV_SCOPE__ .icon .text-icon {
  color: rgb(255, 0, 170);
  position: absolute;
  font-size: 12px;
  left: -37px;
  top: -38px;
}
.__UIV_SCOPE__ .icon svg {
  width: 20px;
  height: 20px;
  border: solid 2px transparent;
  display: flex;
}
.__UIV_SCOPE__ .button:hover .icon svg {
  border: solid 2px rgba(255, 0, 170, 0.692);
}
.__UIV_SCOPE__ .padding-left {
  position: absolute;
  width: 20px;
  height: 2px;
  background-color: rgb(255, 0, 170);
  left: 0;
  top: 50%;
  transform: translateY(-50%);
}
.__UIV_SCOPE__ .padding-left:before {
  content: "";
  width: 2px;
  height: 10px;
  background-color: rgb(255, 0, 170);
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
}
.__UIV_SCOPE__ .padding-left:after {
  content: "";
  width: 2px;
  height: 10px;
  background-color: rgb(255, 0, 170);
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
}
.__UIV_SCOPE__ .padding-left-line {
  position: absolute;
  width: 30px;
  height: 2px;
  background-color: rgb(255, 0, 170);
  left: -24px;
  top: 11px;
  transform: rotate(-50deg);
}
.__UIV_SCOPE__ .padding-left-line::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 6px;
  height: 6px;
  transform: translate(-50%, -50%);
  background-color: rgb(255, 0, 170);
  border-radius: 100%;
}
.__UIV_SCOPE__ .padding-left-text {
  color: rgb(255, 0, 170);
  font-size: 12px;
  position: absolute;
  white-space: nowrap;
  transform: rotate(50deg);
  bottom: 30px;
  left: -67px;
}

.__UIV_SCOPE__ .padding-right {
  position: absolute;
  width: 20px;
  height: 2px;
  background-color: rgb(255, 0, 170);
  right: 0;
  top: 50%;
  transform: translateY(-50%);
}
.__UIV_SCOPE__ .padding-right:before {
  content: "";
  width: 2px;
  height: 10px;
  background-color: rgb(255, 0, 170);
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
}
.__UIV_SCOPE__ .padding-right:after {
  content: "";
  width: 2px;
  height: 10px;
  background-color: rgb(255, 0, 170);
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
}
.__UIV_SCOPE__ .padding-right-line {
  position: absolute;
  width: 30px;
  height: 2px;
  background-color: rgb(255, 0, 170);
  right: -24px;
  top: 11px;
  transform: rotate(50deg);
}
.__UIV_SCOPE__ .padding-right-line::before {
  content: "";
  position: absolute;
  left: 30px;
  top: 0;
  width: 6px;
  height: 6px;
  transform: translate(-50%, -50%);
  background-color: rgb(255, 0, 170);
  border-radius: 100%;
}
.__UIV_SCOPE__ .padding-right-text {
  color: rgb(255, 0, 170);
  font-size: 12px;
  position: absolute;
  white-space: nowrap;
  transform: rotate(-50deg);
  bottom: 33px;
  left: 18px;
}
.__UIV_SCOPE__ .background {
  position: absolute;
}
.__UIV_SCOPE__ .background::before {
  content: "";
  position: absolute;
  right: 27px;
  bottom: -70px;
  width: 100px;
  height: 53px;
  background-color: transparent;
  border-radius: 0px 0px 22px 22px;
  border-right: solid 2px rgb(255, 0, 170);
  border-bottom: solid 2px transparent;
}
.__UIV_SCOPE__ .background::after {
  content: "";
  position: absolute;
  right: 25px;
  bottom: -20px;
  width: 6px;
  height: 6px;
  background-color: rgb(255, 0, 170);
  border-radius: 100%;
}
.__UIV_SCOPE__ .background-text {
  position: absolute;
  color: rgb(255, 0, 170);
  font-size: 12px;
  bottom: -70px;
  left: -115px;
}
.__UIV_SCOPE__ .border {
  position: absolute;
  right: 0;
  top: 0;
}
.__UIV_SCOPE__ .border:before {
  content: "";
  width: 15px;
  height: 15px;
  border: solid 2px rgb(255, 0, 170);
  position: absolute;
  right: 0%;
  top: 0;
  transform: translate(50%, -50%);
  border-radius: 100%;
}
.__UIV_SCOPE__ .border:after {
  content: "";
  width: 2px;
  height: 25px;
  background-color: rgb(255, 0, 170);
  position: absolute;
  right: -10px;
  top: -15px;
  transform: translate(50%, -50%) rotate(60deg);
}
.__UIV_SCOPE__ .border .border-text {
  position: absolute;
  color: rgb(255, 0, 170);
  font-size: 12px;
  right: -112px;
  top: -30px;
  white-space: nowrap;
}
